slog.SetDefault(logger)

// After SetDefault, top-level functions use this logger
slog.Info("message") // Uses the custom logger
```

## 2. Handler Types

### TextHandler
Writes records as key=value pairs separated by spaces:

```go
handler := slog.NewTextHandler(os.Stderr, &slog.HandlerOptions{
    AddSource: true,  // Include source file and line
    Level: slog.LevelDebug,
})
logger := slog.New(handler)
logger.Info("hello", "count", 3)
// Output: time=2022-11-08T15:28:26.000-05:00 level=INFO msg=hello count=3
```

### JSONHandler
Writes records as line-delimited JSON:

```go
handler := slog.NewJSONHandler(os.Stdout, nil)
logger := slog.New(handler)
logger.Info("hello", "count", 3)
// Output: {"time":"2022-11-08T15:28:26.000000000-05:00","level":"INFO","msg":"hello","count":3}
```

### MultiHandler (Go 1.26+)
Sends logs to multiple handlers:

```go
textHandler := slog.NewTextHandler(os.Stdout, nil)
jsonHandler := slog.NewJSONHandler(os.Stderr, nil)
multiHandler := slog.NewMultiHandler(textHandler, jsonHandler)
logger := slog.New(multiHandler)
```

## 3. Log Level Functions

### Log Level Constants
```go
const (
    LevelDebug = -4
    LevelInfo  = 0
    LevelWarn  = 4
    LevelError = 8
)
```

### Logging at Different Levels

```go
// Convenience methods
slog.Debug("debug message", "key", "value")
slog.Info("info message", "key", "value")
slog.Warn("warning message", "key", "value")
slog.Error("error message", "key", "value")

// With context
ctx := context.Background()
slog.DebugContext(ctx, "debug message", "key", "value")
slog.InfoContext(ctx, "info message", "key", "value")

// Generic Log method
slog.Log(ctx, slog.LevelWarn, "custom level", "key", "value")

// Most efficient: LogAttrs (no alternating key-value pairs)
slog.LogAttrs(ctx, slog.LevelInfo, "message",
    slog.Int("count", 3),
    slog.String("status", "ok"),
)
```

## 4. Structured Logging with Key-Value Pairs

### Attribute Functions

```go
// Built-in attribute constructors
slog.String("key", "value")
slog.Int("key", 42)
slog.Int64("key", int64(42))
slog.Uint64("key", uint64(42))
slog.Float64("key", 3.14)
slog.Bool("key", true)
slog.Duration("key", time.Second)
slog.Time("key", time.Now())
slog.Any("key", complexValue)

// Example
logger.Info("user login",
    slog.String("user", "alice"),
    slog.Int("id", 42),
    slog.Bool("verified", true),
)
```

### Attr Type

```go
type Attr struct {
    Key   string
    Value Value
}

// Create and use Attr directly
attr := slog.String("method", "GET")
logger.LogAttrs(ctx, slog.LevelInfo, "request", attr)

// Check equality
if attr.Equal(other) {
    // ...
}
```

## 5. Using slog.With for Adding Context

```go
// Create a logger with common attributes
baseLogger := slog.Default()
requestLogger := baseLogger.With(
    "request_id", "req-123",
    "user", "alice",
)

// All subsequent logs include these attributes
requestLogger.Info("processing started")
requestLogger.Info("processing complete")
// Both include request_id and user

// Chain With calls
logger2 := requestLogger.With("action", "delete")
// Combines attributes from both With calls
```

## 6. HandlerOptions

```go
opts := &slog.HandlerOptions{
    // Minimum log level (default: LevelInfo)
    Level: slog.LevelDebug,

    // Include source file and line number
    AddSource: true,

    // Modify attributes before logging
    ReplaceAttr: func(groups []string, a slog.Attr) slog.Attr {
        // Remove time
        if a.Key == slog.TimeKey && len(groups) == 0 {
            return slog.Attr{}
        }
        // Modify level output
        if a.Key == slog.LevelKey {
            a.Value = slog.StringValue(
                strings.ToUpper(a.Value.String()),
            )
        }
        return a
    },
}

handler := slog.NewTextHandler(os.Stdout, opts)
logger := slog.New(handler)
```

### Dynamic Level Control

```go
// Create a LevelVar for dynamic level changes
var programLevel = new(slog.LevelVar)
programLevel.Set(slog.LevelInfo)

handler := slog.NewJSONHandler(os.Stderr, &slog.HandlerOptions{
    Level: programLevel,
})
slog.SetDefault(slog.New(handler))

// Change level at runtime
programLevel.Set(slog.LevelDebug)
```

